import{_ as t,a as r}from"./chunks/fecdc489471a0d332368.BeQEkJ2q.js";import{_ as l,C as o,o as i,c as n,j as e,a as s,E as h,a6 as u}from"./chunks/framework.CnPv4DE1.js";const x=JSON.parse('{"title":"阻碍你获得想要的生活的7个坏习惯","description":"","frontmatter":{"title":"阻碍你获得想要的生活的7个坏习惯","originalTitle":"7 Bad Habits Preventing You From The Life You Want","date":"2025-05-19","originalUrl":"https://thedankoe.com/letters/7-bad-habits-preventing-you-from-the-life-you-want/","minutes":13,"sourceHash":"5d72d077181e0ea20291e9bbe2fb2f7b721fc47a97e6517947b6e2ac13809fe9","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/7-bad-habits-preventing-you-from-the-life-you-want/"}]]},"headers":[],"relativePath":"letters/7-bad-habits-preventing-you-from-the-life-you-want.md","filePath":"letters/7-bad-habits-preventing-you-from-the-life-you-want.md"}'),m={name:"letters/7-bad-habits-preventing-you-from-the-life-you-want.md"};function d(c,p,b,f,g,_){const a=o("ArticleMeta");return i(),n("div",null,[p[0]||(p[0]=e("h1",{id:"阻碍你获得想要的生活的7个坏习惯",tabindex:"-1"},[s("阻碍你获得想要的生活的7个坏习惯 "),e("a",{class:"header-anchor",href:"#阻碍你获得想要的生活的7个坏习惯","aria-label":'Permalink to "阻碍你获得想要的生活的7个坏习惯"'},"​")],-1)),h(a),p[1]||(p[1]=u('<p>这7个习惯都是心理层面的。</p><p>（其实我认为所有习惯都是心理层面的。）</p><p>它们不是你试图停止的身体行为。</p><p>它们是潜意识的思维过程，导致你原地不动，而不是为你想要的未来采取行动。</p><p>要重新连接你的大脑，需要一些努力。</p><p>所以跟我一起往下看。</p><h3 id="习惯1-不够自私" tabindex="-1">习惯1）不够自私 <a class="header-anchor" href="#习惯1-不够自私" aria-label="Permalink to &quot;习惯1）不够自私&quot;">​</a></h3><p>因为氧气面罩原则同样适用于现实生活：</p><p>如果你想帮助别人，你必须先保障自己的健康状态。</p><p>一个窒息的救援者救不了任何人。</p><p>我们被训练成要在乎自己之前先在乎所有其他人，而那些这样训练我们的人自己却是无意识地自私的。大多数人并不希望你好。他们只想要对自己最有利的东西，如果你不服从，他们就会说服你，让你显得很自私。要避开这个陷阱。它会把你定位为一个可被利用的资源。</p><p>你生命中最重要的人和最重要的工作，值得拥有最好版本的你。</p><p>而当你忽视自己去迎合别人的需求时，他们获得了所有的好处，而你的潜力却在慢慢地流失。</p><p>不要再把自私视为一件负面的事情。</p><p>相反，要变得<em>有策略地自私</em>。</p><p>把自己想象成一块手机电池或一块肌肉。当你充满电或恢复充分时，你表现最好。当你精疲力竭时，你就会关机。大多数人在做任何事情时，都是在零电量的状态下运作的。</p><ul><li><strong>明确不可妥协的事项</strong>——列一份简短的清单，写下你要保持良好状态绝对需要的东西。运动、独处时间、睡眠。要具体。这些是必需品，不是奢侈品。</li><li><strong>说“不”时不必抱歉</strong>——这很难，但要练习不带歉意地说不。直接表明你没空，让别人的反应暴露出他们对你的健康状态有多不在意。</li><li><strong>根据资源筛选请求</strong>——如果你没有精力，如果这件事不重要，如果你必须放弃某个重要的东西，或者如果你会讨厌做这件事，那就<em>拒绝</em>。就这么简单。</li><li><strong>在你充盈有余时才给予</strong>——知道自己需要什么才能正常运作，知道自己需要什么才能发挥最佳状态，也要知道在这些优先事项被满足<em>之后</em>，你还能自由给出什么。</li></ul><p>自私和无私是同一枚硬币的两面。你不能只拥有其中一个而没有另一个，就像你不能只拥有快乐而没有与之对比的悲伤一样。</p><p>这听起来可能像是些基本的建议，但你真的做到了吗？</p><p>如果没有，那你就需要这个提醒，而且不该因为以前听过就把它抛到一边。</p><p>如果你练习变得更自私一点，你的生活质量在一周之内就会有大幅提升。</p><h3 id="习惯2-问-我该怎么开始" tabindex="-1">习惯2）问“我该怎么开始？” <a class="header-anchor" href="#习惯2-问-我该怎么开始" aria-label="Permalink to &quot;习惯2）问“我该怎么开始？”&quot;">​</a></h3><p>请原谅我在这里发发牢骚。</p><p>为什么人们如此执着于错误的东西？</p><p>感觉几乎没有一天不听到人们在问：</p><p>“这要花多长时间？”</p><p>“我该怎么开始？”</p><p>这两个问题都源自一个更深层的问题：“如果我失败了怎么办？”</p><p>我理解。</p><p>你想开始做副业来赚更多的钱。你想去健身房来重建自信。你想做那件难事，好让生活变得更轻松。</p><p>对此我要说：</p><p>它花多少年都无关紧要。</p><p>你他妈还能做什么别的事？</p><p>你不去学习、构建、试验，不去做那些让生活有意义的一切事情，就因为你有更好的事情可做？</p><p>说得通吗，讲点道理。</p><p>你想让生活变得更轻松，是因为它现在很难。但一旦追逐梦想变得艰难，你就放弃了，然后接受自己那艰难的生活？</p><p>真的吗？</p><p>问题在于你的优先事项是个谎言。</p><p>你说你想要成功，但你显然并不想，因为你对成功的渴望，并没有超过你想躺在床上吃多力多滋的渴望。</p><p>你必须意识到，就算它花掉你的一生也无关紧要，因为至少在这个过程中你在成长，而不是在消亡。你一生的事业不是一个结果，它是一个过程。</p><p>接下来是下一个问题：</p><p>“我该怎么开始？”</p><p>你通过开始来开始。</p><p>简单明了。</p><p>想象一下，你是这个世界历史上第一个做你即将要做的事情的人。开始创业、健身塑形、学习一项新技能，无论是什么。</p><p>你觉得那个人有教程可以看吗？有书可以读吗？</p><p>还是说他们犯了一个错误。然后又一个。然后又一个。而不把它称为失败，因为他们明白自己在积累一份<em>不管用的方法</em>的清单，到了某个时刻，考虑到他们积累的所有经验，他们不成功都不可能了。</p><p>这才是开始的真正秘诀：</p><p>表现得就像没有人会明确告诉你该怎么做一样。</p><p>假设你必须完全靠自己去搞清楚。</p><p>我不会给你学习或做任何事情的最佳方法。</p><p>相反，别再关注这个了。</p><p>沉迷其中。学习一切。尝试一切。让它失败。让它显得尴尬和难为情。这是你人生中实现任何有价值之事的唯一方法。</p><h3 id="习惯3-从不点击发布" tabindex="-1">习惯3）从不点击发布 <a class="header-anchor" href="#习惯3-从不点击发布" aria-label="Permalink to &quot;习惯3）从不点击发布&quot;">​</a></h3><p>当我意识到一份传统的坐办公室写字的工作是我存在的祸根时，我开始尝试任何我能找到的“网上赚钱”方法。</p><p>我最终尝试了几乎所有的商业模式，并且几乎都失败了，直到我被迫找一份工作来维持生计。</p><p>所有那些网络生意失败的唯一原因，就是我从来没有点击发布。我会花过多的时间去做标志、网站，以及建立一份免费作品的作品集，好让自己看起来有点权威性。</p><p>正如我所了解到的，你根本不需要这些东西才能成功。</p><p>相反，你需要一批公开的作品，让潜在的客户、雇主和关注者能够真正接触到，从而了解你是做什么的，做得有多好。这才是提高你运气比例的方式。</p><p>从不点击发布会导致一种危险的东西。</p><p>它叫做“进展隐形化”。</p><p>换句话说，你没有<em>现实世界</em>的反馈，也没有给自己一个<em>机会</em>，让自己对坚持下去负起某种责任。</p><p>再换句话说，你实际上什么都没学到。这就像你去上大学，申请一份工作，然后又去上大学。你从没真正开始那份工作……而正是在那份工作中，你才<em>真正学会怎么做这份工作</em>。你学位里的大部分知识都被扔到窗外去了。</p><p>我没有选择不每周写通讯的余地。我没有选择不做产品并推广它们的余地。有人在等着这些东西，我整个人的生存都依赖于此。我<em>必须</em>做（而且我<em>想</em>做），因为我对其他所有事情都说了不，包括那份工作。而对你来说，这是可选的，因为你有一个B计划——也就是你正试图逃离的当前生活方式，因为你不喜欢它，这一点也说不通。</p><p>最后，从不公开自己的作品是一种通过孤立而产生的现实扭曲。</p><p>你完全独自工作，没有社群、没有客户、没有反馈、没有责任问责。在这种环境下，维持自我欺骗很容易。</p><p>因为你没有现实的检验，所以很容易为自己关于“多努力”工作以及缺乏成果的谎言找到借口。</p><p>点击发布吧。</p><p>如果你不知道该发布什么，这篇文章可能是我最不受欢迎的付费文章之一，因为最不轰动的东西通常最有效，却得到最少的关注。在其中，我教授了3种练习方式，让你在Substack notes、LinkedIn、X或其他任何平台上练习写短篇内容表达自己的想法。<a href="https://thedankoe.substack.com/p/3-drills-to-become-a-master-at-short" target="_blank" rel="noreferrer">点击查看。</a></p><h3 id="习惯4-制造人为的复杂性" tabindex="-1">习惯4）制造人为的复杂性 <a class="header-anchor" href="#习惯4-制造人为的复杂性" aria-label="Permalink to &quot;习惯4）制造人为的复杂性&quot;">​</a></h3><p>简而言之：</p><p>比你笨的人正在取得比你多十倍的进步和财富，因为他们思考得少，行动得多。</p><p>我说的就是那些读了我的商业内容，然后想“哦，这太基础了”的人。</p><p>仿佛我在骗你，说这些东西就是成功所需的一切。</p><p>问题在于，你在潜意识里维持着围绕商业基本原理的人为复杂性，来为自己的不行动找借口。你相信商业上的成功需要某种别人对你隐藏的神秘秘密，所以你不断堆积更多没用的知识，只会让你越来越慢。</p><p>为了避免复杂性，我会把这一部分说得简短一些。</p><p>你需要的是对基本原理持续不断的执行。</p><p>如果你需要一门比入门级更高的课程才能行动或看到结果，那<em>你一定在什么地方做错了</em>。</p><p>学习基本原理。</p><p>开始。犯错。从错误中学习。</p><p>这就是蓝图：根本没有蓝图。</p><p>冲浪者不需要蓝图来应对海浪的反馈。他们已经失败和练习了足够多次，达到了第二天性的程度。</p><p>这些习惯之间的一个共同主题是，你从来没有真正带着坚持和迭代去把那件该死的事情做出来。</p><h3 id="习惯5-过度节俭" tabindex="-1">习惯5）过度节俭 <a class="header-anchor" href="#习惯5-过度节俭" aria-label="Permalink to &quot;习惯5）过度节俭&quot;">​</a></h3><p><img src="'+t+'" alt=""></p><p>大多数人都在金钱上挣扎。</p><p>这是一个事实。</p><p>金钱与现代人的生存深深地交织在一起。</p><p>它影响着你生活的每一个领域。即使你没有在想钱，你其实也在想钱。你的健康取决于你的钱。你人际关系的理智程度取决于一个基本的金钱数额。</p><p>你可以说这不公平，可以抱怨它本该不同，但我强烈不同意这种说法。</p><p>我不是来告诉你，关于金钱的真相曾被某种方式“隐藏”起来不让你知道。</p><p>你陷入这种境地，既是你的错，也不完全是你的错。</p><p>你从未质疑过自己被养育的方式，因此发展出了一种糟糕的、关于金钱的心理关系，也正因为如此，你没能理解赚钱本身是一项技能。你可以赚到你想要的任何数额，只是你没有花时间去研究、练习并精通这项技能。</p><p>金钱问题并不存在。心理问题才存在。</p><p>大多数人无法赚钱、留住钱或聪明地使用钱，归根结底是因为他们的信念，因为你的信念决定了你能<em>注意到</em>哪些机会去做这些事情。</p><p>以下是普通人关于金钱的一些常见信念：</p><ul><li>你相信钱很难赚。</li><li>你不相信金钱是一个像健康、人际关系或你的创意工作一样的精通领域。</li><li>你可能相信金钱是邪恶的（因为你曾被之前的负面经历所“编程”）。</li><li>你对创业不感兴趣，因为你只看到那些爱夸夸其谈的油腻推销员和每周80小时的工作时间这一小部分人。</li><li>你认为每个人都在试图骗你，或者认为任何非巨型企业都是骗子（尽管它们通常正是你说自己支持的那些独立企业）。</li><li>你被困在生存模式中，所以你看不到自我发展或商业的重要性，并感到有一种冲动想把它们一笔带过，好让自己对自己的行为感觉好一点。</li><li>你不认为自己在自己的领域能赚到很多钱，而这纯粹是错的，你只需要观察一下你所在领域的顶尖收入者就知道了（提示：他们都有自己的生意）。</li></ul><p>这其中每一条都在限制着你能赚到多少钱。</p><p>如果你相信金钱不是一种技能，你就不会去学习这项技能。</p><p>如果你相信金钱是邪恶的，那么即使赚更多钱是你摆脱自己造成的混乱局面的唯一途径，你也会对赚更多钱的想法感到排斥。</p><p>你对金钱的认知，是由你的发展水平决定的。</p><p>解决你金钱问题（也是心理问题）的方法，就是一级一级地往上走。</p><p>金钱的目的会随着你的自我发展而改变。它最开始只是一种生存手段，然后变成获取地位的方法，进而引发对自主权的渴望，接着成为创造力和表达的燃料，最终转变为一种帮助他人经历类似阶段的方式——无论是否与金钱有关。</p><p>以下是这几个层级：</p><ul><li><strong>生存</strong> —— 你目前在人生的财务领域处于生存层级（在健康或智力等其他领域你可能处于更高层级）。</li><li><strong>地位</strong> —— 当（1）你对金钱有了安全感，且（2）你意识到需要让别人认为你有价值，才能更好地生存下去时，你就进入了地位阶段。</li><li><strong>创造力</strong> —— 你意识到地位游戏的种种弊端，开始渴望自主权，并对自己的手艺发展出一种哲学层面的精通感。在长期遵循他人方法之后，你开始创造属于自己的做事方式。</li><li><strong>贡献</strong> —— 你把自己发展到无法再被雇佣的地步。工作、休息和玩乐之间的界限变得难以区分。</li></ul><p>每当上一个层级痛苦到无法再停留时，你就会超越它，进入下一个层级。你会知道那一刻何时到来。</p><p>眼下，你只需要意识到这条路径的存在，就足以治愈“节俭”这个习惯。把它记在心里。</p><p>你也可以浏览<a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex 内置的</a> 25 个以上预先构建的 AI 工作流，来发现你到底想从生活中得到什么、如何把它变成一种现代商业模式，以及其他可能改变你人生方向的事情。（而且，把笔记、PDF 和所有 AI 模型都放在一个地方，也没什么坏处。）</p><p><img src="'+r+'" alt=""></p><h3 id="坏习惯-6-尽量减少预期中的遗憾" tabindex="-1">坏习惯 6）尽量减少预期中的遗憾 <a class="header-anchor" href="#坏习惯-6-尽量减少预期中的遗憾" aria-label="Permalink to &quot;坏习惯 6）尽量减少预期中的遗憾&quot;">​</a></h3><blockquote><p>你所寻找的魔法，就藏在你正在回避的那份工作里。</p></blockquote><p>虽然我认为你真正寻找的魔法，其实藏在你正在回避的实验之中——只是你看不到，因为你脑子里只有“回避这份工作”这一件事——但这句话确实道出了一丝真相。</p><p>几乎没有哪一天，人们不会问：</p><ul><li>“我该从哪个平台开始？”</li><li>“我该创建什么样的数字产品？”</li><li>“我该开一家服务型企业？做电商？还是别的？”</li></ul><p>然后，当他们终于做出决定后，又会经历一个“过早优化”的阶段。</p><p>就像我之前几次创业尝试那样，我把精力都放在网站、logo，以及私下打磨作品集上，直到自己感觉“准备好了”——而那个时刻永远不会到来。</p><p>你做决定，主要是为了避免未来的负面情绪，而不是为了最大化正面结果。你在潜意识里是在“为了不输而打”，而不是“为了赢而打”，因为在你内心深处，你其实并不真的想赢。</p><p>解决办法在于换个视角。</p><p>你会更后悔哪一种情况？</p><p>是走错了路——而这恰恰是找到正确道路的唯一方式——并借此获得比你人生中任何时候都更多的经验……</p><p>还是原地不变。</p><p>这不是一个很难做的决定。</p><p>去做能带来结果的工作，其余的都别管。</p><p>如果你以为在开始获得客户之前，必须先有网站、logo和公司注册（LLC），或者认为你需要先想出完美的数字产品或商业模式才能开始赚钱，那你就是在自欺欺人。</p><p>我会在以后的一篇信件里详细谈这个话题。</p><h3 id="坏习惯-7-执着于一个无益于你目标的身份" tabindex="-1">坏习惯 7）执着于一个无益于你目标的身份 <a class="header-anchor" href="#坏习惯-7-执着于一个无益于你目标的身份" aria-label="Permalink to &quot;坏习惯 7）执着于一个无益于你目标的身份&quot;">​</a></h3><p>你没有到达自己想去的地方，是因为你还不是那个能到达那里的人。</p><p>当人们想要改变生活时，他们总想在不做太多改变的情况下实现它。</p><ul><li>他们想减肥，却不愿放弃自己爱吃的食物。</li><li>他们想赚更多钱，却仍然每个周末都出去玩。</li><li>他们想进入一段恋爱关系，却依旧邋里邋遢。</li></ul><p>我不是说你不能一边做这些事一边看到结果。</p><p>我是说，你没有得到那些结果，是因为你目前的生活方式根本无法带来那些结果。</p><p>问题是，所有这些事情其实都是可以选择的。</p><p>你之所以爱吃甜食或炸食，仅仅是因为它们已经变成了习惯。你把它们做到了一种程度，以至于觉得没有它们，人生就会变得很糟糕。</p><p>如果你真的想改变，就得把创可贴一下撕掉。</p><p>你需要在一夜之间跳进一个全新的身份里。</p><p>你需要令人不适地清楚意识到：你之所以停留在现在的位置，正是因为你此刻所做的这些事，才让你停留在这里。</p><p>放弃你现在的习惯，你不会因此死掉。</p><p>你可能会经历一段短暂的痛苦，但这就跟翻修房子时会发生的一样。它不会感觉一样，但只要你坚持继续装修下去，你就会塑造出一个让这一切都值得的身份。</p><p>感谢你的阅读。</p><p>——丹（Dan）</p><h3 id="当你准备好时-我能如何帮助你" tabindex="-1">当你准备好时，我能如何帮助你： <a class="header-anchor" href="#当你准备好时-我能如何帮助你" aria-label="Permalink to &quot;当你准备好时，我能如何帮助你：&quot;">​</a></h3><ul><li>上周我发布了一份<a href="https://thedankoe.substack.com/p/mega-guide-how-to-create-your-first" target="_blank" rel="noreferrer">创建你第一个数字产品的超级指南</a>。这周我会发布一份完整指南，教你为该产品撰写一封有说服力的落地页文案。</li><li>如果你需要一个新的地方来存放你的笔记和知识，<a href="https://kortex.co/" target="_blank" rel="noreferrer">试试 Kortex</a>。里面有 25 个以上的 AI 工作流，可用于学习、营销和创作，此外你还可以在与任何模型的 AI 对话中，引用你的任何笔记、划线高亮、PDF，甚至 YouTube 链接。</li><li>昨天我发布了一段 YouTube 视频，讲的是那套改变了我人生的深度工作routine。如果你正在散步，或者刚好有点空闲时间，想找些好点子，<a href="https://youtu.be/kLd5AvsLWAc" target="_blank" rel="noreferrer">点这里观看</a>。</li></ul><hr><p><a href="/en/letters/7-bad-habits-preventing-you-from-the-life-you-want">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',144))])}const P=l(m,[["render",d]]);export{x as __pageData,P as default};
